<script setup lang="ts">
import { computed, ref } from 'vue';
import type { Telemetry } from './api';
const props=defineProps<{samples:Telemetry[];plot:'phase'|'dq'|'velocity'|'vbus'|'temperature';paused:boolean;table:boolean;dark:boolean}>();
const emit=defineEmits<{ 'update:plot':[value:'phase'|'dq'|'velocity'|'vbus'|'temperature'];'update:paused':[value:boolean];'update:table':[value:boolean] }>();
const hover=ref<number|null>(null);
const series=computed(()=>{const c=props.dark?['#4b9661','#5d82c2','#b07832']:['#368b50','#6389c6','#bd8545'];return props.plot==='phase'?[{key:'ia' as const,label:'Ia',color:c[0]!,unit:'A'},{key:'ib' as const,label:'Ib',color:c[1]!,unit:'A'},{key:'ic' as const,label:'Ic',color:c[2]!,unit:'A'}]:props.plot==='dq'?[{key:'id' as const,label:'Id',color:c[0]!,unit:'A'},{key:'iq' as const,label:'Iq',color:c[1]!,unit:'A'}]:props.plot==='velocity'?[{key:'velocity' as const,label:'机械速度',color:c[0]!,unit:'rad/s'}]:props.plot==='vbus'?[{key:'vbus' as const,label:'母线电压',color:c[1]!,unit:'V'}]:[{key:'temperature' as const,label:'温度',color:c[2]!,unit:'°C'}]});
const range=computed(()=>{const values=props.samples.flatMap(s=>series.value.map(x=>Number(s[x.key])));if(!values.length)return{min:0,max:1};let min=Math.min(...values),max=Math.max(...values);if(max-min<1e-6){min-=1;max+=1}else{const pad=(max-min)*.06;min-=pad;max+=pad}return{min,max}});
function xAt(i:number){const d=props.samples;if(d.length<2)return 40;const first=d[0]!.time,last=d.at(-1)!.time;return 40+(last>first?(d[i]!.time-first)/(last-first):i/(d.length-1))*750}
function path(key:keyof Telemetry){const d=props.samples;if(d.length<2)return '';return d.map((s,i)=>{const x=xAt(i),y=94-(Number(s[key])-range.value.min)/(range.value.max-range.value.min)*82;return `${i===0||s.time-d[i-1]!.time>.2?'M':'L'}${x.toFixed(1)},${y.toFixed(1)}`}).join(' ')}
function move(e:MouseEvent){const rect=(e.currentTarget as SVGSVGElement).getBoundingClientRect();const x=(e.clientX-rect.left)/rect.width*800;const t=(Math.max(40,Math.min(790,x))-40)/750;const time=props.samples[0]!.time+t*(props.samples.at(-1)!.time-props.samples[0]!.time);let best=0;for(let i=1;i<props.samples.length;i++)if(Math.abs(props.samples[i]!.time-time)<Math.abs(props.samples[best]!.time-time))best=i;hover.value=best}
const selected=computed(()=>hover.value===null?undefined:props.samples[hover.value]);
</script>
<template><div class="chart-tools"><div class="legend"><span v-for="s in series" :key="s.label"><i :style="{background:s.color}"></i>{{s.label}} <small>{{s.unit}}</small></span></div><select :value="plot" @change="emit('update:plot',($event.target as HTMLSelectElement).value as typeof plot)"><option value="phase">三相电流 · A</option><option value="dq">dq 电流 · A</option><option value="velocity">机械速度 · rad/s</option><option value="vbus">母线电压 · V</option><option value="temperature">温度 · °C</option></select><label class="pause"><input type="checkbox" :checked="paused" @change="emit('update:paused',($event.target as HTMLInputElement).checked)">暂停图表显示</label><button class="soft-button" @click="emit('update:table',!table)">{{table?'图表视图':'数据表'}}</button></div><div v-if="!table" class="plot"><svg viewBox="0 0 800 120" preserveAspectRatio="none" role="img" aria-label="实时遥测折线图" @mousemove="samples.length&&move($event)" @mouseleave="hover=null"><path v-for="(y,i) in [15,38,61,84,107]" :key="i" :d="`M40 ${y} H790`" class="gridline"/><text x="4" y="17">{{range.max.toFixed(2)}}</text><text x="4" y="108">{{range.min.toFixed(2)}}</text><path v-for="s in series" :key="s.label" :d="path(s.key)" fill="none" :stroke="s.color" stroke-width="2" vector-effect="non-scaling-stroke"/><path v-if="selected" :d="`M${xAt(hover!)} 10 V108`" class="crosshair"/></svg><div v-if="selected" class="tooltip">{{selected?.time.toFixed(3)}} s · {{series.map(s=>`${s.label} ${Number(selected?.[s.key]).toFixed(2)} ${s.unit}`).join(' · ')}}</div><div v-if="!samples.length" class="empty-overlay">等待遥测数据<small>连接后开始接收设备遥测</small></div><div class="x-axis"><span>{{samples[0]?.time.toFixed(2)??'—'}} s</span><span>{{samples.at(-1)?.time.toFixed(2)??'—'}} s · 最近 {{samples.length}} / 600 帧</span></div></div><table v-else class="data-table"><thead><tr><th>时间 / s</th><th v-for="s in series" :key="s.label">{{s.label}} / {{s.unit}}</th><th>序号</th></tr></thead><tbody><tr v-for="s in samples.slice(-10).reverse()" :key="s.sequence"><td>{{s.time.toFixed(3)}}</td><td v-for="ser in series" :key="ser.label">{{Number(s[ser.key]).toFixed(3)}}</td><td>{{s.sequence}}</td></tr></tbody></table><div class="chart-foot">显示缓冲最多 600 帧；约 20 Hz，非 100 kHz 控制环采样。序号来自 ADC 帧，不代表链路丢包计数。</div></template>
